import{_ as l,o as e,c as i,a2 as r}from"./chunks/framework.DfDAiEgj.js";const u=JSON.parse('{"title":"笔试题","description":"","frontmatter":{},"headers":[],"relativePath":"interview/exam.md","filePath":"interview/exam.md","lastUpdated":null}'),t={name:"interview/exam.md"};function o(p,a,h,n,d,s){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="笔试题" tabindex="-1">笔试题 <a class="header-anchor" href="#笔试题" aria-label="Permalink to &quot;笔试题&quot;">​</a></h1><h2 id="题型" tabindex="-1">题型 <a class="header-anchor" href="#题型" aria-label="Permalink to &quot;题型&quot;">​</a></h2><p>行测题一般由以下几种题型组成：<a href="https://zhuanlan.zhihu.com/p/83786056" target="_blank" rel="noreferrer">1</a></p><ol><li>阅读理解</li><li>数据计算</li><li>逻辑推理</li><li>数字推理</li><li>图形推理</li></ol><h2 id="解题技巧" tabindex="-1">解题技巧 <a class="header-anchor" href="#解题技巧" aria-label="Permalink to &quot;解题技巧&quot;">​</a></h2><h3 id="阅读理解题" tabindex="-1">阅读理解题 <a class="header-anchor" href="#阅读理解题" aria-label="Permalink to &quot;阅读理解题&quot;">​</a></h3><p>① 排除法，错误项一般都有以偏概全、无中生有、偷换概念、太过绝对、与题矛盾等错误；</p><p>② 还有一个技巧是“优先选首尾，优先选宏观”，指的是首尾部分往往是文段的主旨，答案越宏观越可靠。</p><h3 id="数据计算题" tabindex="-1">数据计算题 <a class="header-anchor" href="#数据计算题" aria-label="Permalink to &quot;数据计算题&quot;">​</a></h3><p>增长量与增长率：增长量 = 现期量 - 基期量 增长率 = 增长量 / 基期量 * 100% 同比与环比：同比是指和相同时期相比，比如与去年同月相比；环比指与相连的上一个统计周期相比，比如与上个季度相比。</p><h3 id="逻辑推理题" tabindex="-1">逻辑推理题 <a class="header-anchor" href="#逻辑推理题" aria-label="Permalink to &quot;逻辑推理题&quot;">​</a></h3><p>第一步：写推理公式，(1) W → X (2) -T → -S (3) T → -X，X → -T (4) Y且Z → W</p><p>第二步：写逆否公式，原命题成立则逆否命题必然成立，(1&#39;) -X → -W (2&#39;) S → T (3&#39;) X → -T，T → -X (4&#39;) -W→ -Y或-Z</p><p>第三步：代入初始条件进行推导，现在接通S和Z，由(2&#39;)式得T必然接通，由(3)式得X必然断开，由(1&#39;)式得W必然断开，由(4&#39;)式得Y和Z至少一个断开，得出-Y（注意：原命题和逆否命题等价，所以每个条件选一个用一次就行了）</p><p>第四步：得出结论，于是正确答案是S、T、-W、-X、-Y、Z，选A</p><h3 id="数字推理题" tabindex="-1">数字推理题 <a class="header-anchor" href="#数字推理题" aria-label="Permalink to &quot;数字推理题&quot;">​</a></h3><p>① 基本数列：背下来！</p><p>等差数列：1,3,5,7,9 等比数列：2,4,8,16,32 质数列：2,3,5,7,11,13 平方数列：1,4,9,16,25 立方数列：1,8,27,64,125</p><p>② 含分数数列：遇到含分数的数列，可以尝试全部化为分数形式，尝试单独寻找分子分母数列的规律，例题可写成2/1,4/2,8/3,16/4，分子分母分别为等比和等差数列，可知正确答案为D</p><p>③ 奇偶组合数列：数列的奇数项和偶数项分别是有规律的数列，需要分开找规律（这类题一般给的数比较多）</p><p>④ 裂项数列：数列的项可以拆分，拆分出来的子数列呈一定规律，如2,12,30可以拆分为1×2，3×4，5×6，或2030600,1015150,1512180可以拆分为20×30=600，10×15=150，15×12=180（这类题一般给的项比较少）</p><p>⑤ 递推数列：一般是由前两项推第三项，推导的方法各异（也有<strong>前三项推第四项</strong>）</p><p>加减运算：1,3,4,7,11,18（c=a+b）</p><p>乘除运算：2,2,4,8,32,256（c=a×b）</p><p>组合运算：4,2,4,6,20,114（c=a×b-a）</p><p>⑥ 孪生数列：数列连起来没有任何规律，一般是找两个两个间的规律，例如3,8,1,0,6,35,4,15，这个数列每两个一组就很容易看出规律，所以一般会给出7个数，求第8项</p><p>⑦ 特殊数列：一些脑洞大开的数列，直接计算不出啥规律，如8324,669,4054,80173，每个数都有三个封闭空间，所以必须选符合这个规律的选项</p><h3 id="图形推理题" tabindex="-1">图形推理题 <a class="header-anchor" href="#图形推理题" aria-label="Permalink to &quot;图形推理题&quot;">​</a></h3><ol><li>对称轴规律：具有相同对称关系，对称轴数量、对称轴方向相同等</li><li>是否一笔画</li><li>布尔运算规律：两个图形叠加得第三个图形</li><li>旋转、对称、平移运动规律</li><li>数量规律：点（交点数、端点数）、线（线数、曲线数、直线数）、面（封闭域数）、角（角数）、素（每种图形的数量，图形种数）</li><li>接触规律：点接触、面接触</li></ol><h2 id="主观题解题技巧" tabindex="-1">主观题解题技巧 <a class="header-anchor" href="#主观题解题技巧" aria-label="Permalink to &quot;主观题解题技巧&quot;">​</a></h2><h3 id="需求分析法则" tabindex="-1">需求分析法则 <a class="header-anchor" href="#需求分析法则" aria-label="Permalink to &quot;需求分析法则&quot;">​</a></h3><ul><li>市场调查部：负责玩家调查研究、对于市场游戏趋势开展研究。进行市场调查很需要资金，当然需要的资金投入越多获得的分析报告将更详尽，对公司的作用越大。</li><li>策划部：策划是游戏的总工程师，其作用不言而喻。没有资金的支持可不行。</li><li>程序部：游戏说到底也还是一个程序，程序研发的投入每家公司都很重视。</li><li>美术部：精美的场景、酷炫的人物和怪物、特有的光效对吸引玩家来说是多么重要。</li><li>技术部：服务器的采购、运维、防黑客、防病毒少得了资金投入吗？</li><li>测试部：没有游戏的测试，一大堆BUG的游戏是没有人喜欢的，对测试的投入不容忽视。 运营部：投放广告、游戏推广、营销策划、渠道管理等不投入怎么行？</li></ul><h3 id="对比分析法则" tabindex="-1">对比分析法则 <a class="header-anchor" href="#对比分析法则" aria-label="Permalink to &quot;对比分析法则&quot;">​</a></h3><p>对比分析法则：往竞品上联想，和同类型产品对比、和另一类人作对比，对比一下你就知道该做啥了</p><p>为了扩大百度百家号的影响力，百家号布局短视频领域，为了帮助短视频创业者们在现实的竞争市场突围，推出了百万年薪计划，为有潜力的优质短视频创作者提供更好的流量扶持和品牌曝光，让更多优秀的短视频作者获得百万年薪。如何为百万年薪计划设置优质短视频评价体系？</p><p>解题指导：可以和最熟悉的大学老师做个对比。大牛教授（院士、长江），类比KOL，这些人得砸钱，不要看他创作了多少内容，而是名人效应；领基本工资的小讲师，类比新手作者，不能因为知名度低就一分不给，要有新人保护机制；一些科研冷门专业的老师，类比小众领域作者，他们创作内容虽然受众少，但是生命周期比蹭热点的内容长，长期来看也很有价值，为了防止他们分不到钱所以得把工作量考虑进去；学校也会按成果评title发工资，所以最终还是要建立起结果导向的评价体系，依据观看、点赞、评论、收藏等指标来发钱。</p><h3 id="场景模拟法则" tabindex="-1">场景模拟法则 <a class="header-anchor" href="#场景模拟法则" aria-label="Permalink to &quot;场景模拟法则&quot;">​</a></h3><p>场景模拟法则：如果让你做一个东西，你就在脑海中模拟购买到使用的完整过程，从而发现用户需要</p><p>例题：给盲人设计一款闹钟</p><p>解题指导：盲人看不见但听得见，可以听收音机，所以可以做电台购物营销让盲人了解到你的产品；盲人使用时首先需要调时间，但是他看不见，所以要有语音播报功能；早上闹钟响后需要关掉，盲人要在黑暗中摸索，所以可以做个枕下闹钟，关闭按钮需要往大了做才能摸到；盲人视觉退化，听觉一般很灵敏，所以最好可以调节声音大小；盲人醒来后白天太寂寞了，可以加上电台功能，可以当收音机使用</p><h3 id="商业价值法则" tabindex="-1">商业价值法则 <a class="header-anchor" href="#商业价值法则" aria-label="Permalink to &quot;商业价值法则&quot;">​</a></h3><p>商业价值法则：出题人虽然没有要求你考虑变现，但是你要是能想到就是加分项</p><p>例题：给你100元在一个陌生城市生活7天，怎么规划？</p><p>解题指导：不能光想着合理分配，应该在能保证解决基本生活需求前提下，剩下的钱第一天就全部投出去挣钱，实现商业价值最大化，比如去批发市场买小玩意儿，然后去学校门口卖，挣第一桶金</p><h2 id="常用面试题-2" tabindex="-1">常用面试题 <a href="https://zhuanlan.zhihu.com/p/23664545" target="_blank" rel="noreferrer">2</a> <a class="header-anchor" href="#常用面试题-2" aria-label="Permalink to &quot;常用面试题 [2]&quot;">​</a></h2><ol><li><p>考察笔试者对安卓规范掌握程度,4.0以前的规范还未成形,因此不那么重要</p></li><li><p>考察笔试者的收集分析能力,从这里可以看出应试者涉及产品领域的广度</p></li><li><p>考察笔试者对产品发展趋势的关注度与理解</p></li><li><p>了解笔试者是否随大流,是否有自己独特的兴趣</p></li><li><p>考察笔试者的用户需求挖掘能力,同时免费给面试官的视频项目搜集用户需求</p></li><li><p>考察面试者在以往的工作中对自己的产品是否有深入思考 是否有找到用户痛点,核心用户群,是否满足核心用户的需求</p></li><li><p>考察面试者对硬件的了解</p></li><li><p>考察笔试是否是面试者的真实成绩,同时,面试的双向交流比笔试的单向交流更能了解面试者的产品素质</p></li><li><p>考察面试者是否对自己常使用的产品有过思考</p></li><li><p>考察面试者对UI,交互,特色功能的掌握与理解</p></li><li><p>考察面试者对UI的理解(可能由于纯银的产品小清新居多,所以比较看重UI)</p></li><li><p>考察面试者的信息搜集能力,从侧面了解面试者在互联网行业所处层次 (如,连dribble都不去的设计师,设计水平不会有多高)</p></li><li><p>考察面试者是否对自己常使用的产品有过思考</p></li><li><p>考察面试者的数据分析能力</p></li><li><p>考察面试者的项目沟通与协作能力</p></li></ol><h3 id="数据分析类" tabindex="-1">数据分析类 <a class="header-anchor" href="#数据分析类" aria-label="Permalink to &quot;数据分析类&quot;">​</a></h3><ol><li>产品上线后最需要关注的指标有哪些？请分别阐述（腾讯）</li><li>某一天，百度的用户检索量下降5%，请分析可能的原因。（百度）<a href="https://www.zhihu.com/question/382522778/answer/1811915139" target="_blank" rel="noreferrer">3</a></li></ol><h3 id="产品运营类" tabindex="-1">产品运营类 <a class="header-anchor" href="#产品运营类" aria-label="Permalink to &quot;产品运营类&quot;">​</a></h3><ol><li>产品假设今天你开了一家经营生鲜品类的淘宝店，你怎么获取第一批用户，并能够运营起来？（阿里巴巴）</li><li>如果你是一名广告主，给你2千万在中国为“炉石传说”（暴雪公司出品的一款魔兽世界题材的卡牌类移动网游）做广告宣传，你打算怎么花？（百度商业产品）<a href="https://www.zhihu.com/question/382522778/answer/1811915139" target="_blank" rel="noreferrer">3</a></li></ol>',50)])])}const b=l(t,[["render",o]]);export{u as __pageData,b as default};
